/**
 * Component review page (milestone 1): the design tokens, typography and core
 * components, shown before any flow is built. Components render in the
 * current language with real core text from the committed fixtures (the synthetic result
 * in fixtures/frontal_ok.*.json, generated by scripts/gen_fixtures.py). The page's own
 * labels are English only: it is a review tool, not part of the product.
 */
import { useId, useState, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { useLocation, useNavigate } from "react-router";
import configEn from "../../fixtures/client_config.en.json" with { type: "json" };
import configTh from "../../fixtures/client_config.th.json" with { type: "json" };
import frontalEn from "../../fixtures/frontal_ok.en.json" with { type: "json" };
import frontalTh from "../../fixtures/frontal_ok.th.json" with { type: "json" };
import overlayEn from "../../fixtures/overlay_ok.en.jpg";
import overlayTh from "../../fixtures/overlay_ok.th.jpg";
import photoUrl from "../../fixtures/photo.jpg";
import profilePhotoUrl from "../../fixtures/profile.jpg";
import profileEn from "../../fixtures/profile_ok.en.json" with { type: "json" };
import profileTh from "../../fixtures/profile_ok.th.json" with { type: "json" };
import { ApiError } from "../api/client";
import type { Point } from "../api/scan";
import { AdjustView } from "../components/adjust/AdjustView";
import { makeTrack } from "../components/adjust/contour";
import {
  BackgroundDrawing,
  HairlineDrawing,
  HelperDistanceDrawing,
  LevelDrawing,
  NeutralDrawing,
  SelfieDrawing,
  ZoomDrawing,
} from "../components/illustrations/Guide";
import {
  AlarCreaseDrawing,
  ProfileBackgroundDrawing,
  ProfileGazeDrawing,
  ProfileHairDrawing,
  ProfileNeckDrawing,
  ProfileTurnDrawing,
} from "../components/illustrations/Profile";
import { ConfirmDialog } from "../components/ui/ConfirmDialog";
import { PhotoViewer } from "../components/viewer/PhotoViewer";
import { FacingChoice } from "./scan/FacingChoice";
import { ScanErrorPanel } from "./scan/ScanErrorPanel";
import { AnalyzeResponseSchema, ClientConfigSchema, type Facing, type Metric } from "../api/schemas";
import { Screen } from "../components/layout/Screen";
import { TopBar } from "../components/layout/TopBar";
import { MeasurementSheet } from "../components/results/MeasurementSheet";
import { MetricRow } from "../components/results/MetricRow";
import { RangeBar, type RangeBarStatus } from "../components/results/RangeBar";
import { ScanMeta } from "../components/results/ScanMeta";
import { Button } from "../components/ui/Button";
import { Checkbox } from "../components/ui/Checkbox";
import { ErrorMessage } from "../components/ui/ErrorMessage";
import { Notice } from "../components/ui/Notice";
import { ProgressLine } from "../components/ui/ProgressLine";
import { RadioCards } from "../components/ui/RadioCards";
import { SegmentedControl } from "../components/ui/SegmentedControl";
import { TextField } from "../components/ui/TextField";
import { currentLanguage } from "../i18n";
import { SEXES, type Sex } from "../scan/subject";
import { step } from "./steps";

const COLOR_TOKENS: ReadonlyArray<[string, string]> = [
  ["--paper", "page background"],
  ["--surface", "measurement sheet, inputs"],
  ["--ink", "primary text, primary button"],
  ["--ink-2", "secondary text, in-range marker"],
  ["--ink-3", "metadata"],
  ["--line", "hairline dividers (decorative)"],
  ["--line-strong", "input borders, range-bar ticks"],
  ["--accent", "links, focus, selected, out-of-range"],
  ["--accent-band", "reference band"],
  ["--notice", "notice background"],
  ["--viewer", "photo surround"],
  ["--error", "form validation (subject only)"],
];

const TYPE_SCALE: ReadonlyArray<[string, string]> = [
  ["text-2xl", "28 px · h1"],
  ["text-xl", "22 px"],
  ["text-lg", "18 px · h2"],
  ["text-base", "16 px · body"],
  ["text-sm", "14 px · secondary, metadata"],
];

const RANGE_EXAMPLES: ReadonlyArray<{ label: string; value: number; status: RangeBarStatus }> = [
  { label: "within", value: 0.333, status: "within" },
  { label: "above", value: 0.356, status: "above" },
  { label: "below", value: 0.311, status: "below" },
  { label: "beyond the scale, low (pinned)", value: 0.2, status: "below" },
  { label: "beyond the scale, high (pinned)", value: 0.5, status: "above" },
];

function Section({ title, children }: { title: string; children: ReactNode }) {
  const id = useId();
  return (
    <section aria-labelledby={id} className="border-t border-line py-8">
      <h2 id={id} lang="en" className="mb-4 text-xl">
        {title}
      </h2>
      {children}
    </section>
  );
}

function Label({ children }: { children: ReactNode }) {
  return (
    <p lang="en" className="mb-2 text-sm text-ink-3">
      {children}
    </p>
  );
}

function Swatch({ name, use }: { name: string; use: string }) {
  // Read from the stylesheet, so the page always shows what tokens.css defines.
  const hex = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return (
    <li className="flex items-center gap-3">
      <span className="size-12 shrink-0 border border-line" style={{ background: `var(${name})` }} />
      <span lang="en" className="text-sm">
        <span className="font-medium">{name}</span> <span className="tabular-nums text-ink-3">{hex}</span>
        <br />
        <span className="text-ink-2">{use}</span>
      </span>
    </li>
  );
}

/** Metrics that show each status and caveat the fixture has, in the API's order. */
function sampleMetrics(metrics: Record<string, Metric>): Metric[] {
  const seen = new Set<string>();
  const out: Metric[] = [];
  for (const m of Object.values(metrics)) {
    const kind = `${m.status}:${m.confidence}`;
    if (!seen.has(kind)) {
      seen.add(kind);
      out.push(m);
    }
  }
  return out;
}

export function ComponentsScreen() {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { key } = useLocation();
  // Opened directly (the page's first entry), back goes to the start of the app instead of leaving it.
  const back = () => (key === "default" ? navigate("/", { replace: true }) : navigate(-1));
  const language = currentLanguage();
  const config = ClientConfigSchema.parse(language === "th" ? configTh : configEn);
  const response = AnalyzeResponseSchema.parse(language === "th" ? frontalTh : frontalEn);
  if (response.status !== "ok") throw new Error("fixture frontal_ok is not ok");
  const result = response.result;
  const side = AnalyzeResponseSchema.parse(language === "th" ? profileTh : profileEn);
  if (side.status !== "ok") throw new Error("fixture profile_ok is not ok");
  const [sex, setSex] = useState<Sex | null>("female");
  const [facing, setFacing] = useState<Facing>("right");
  const [tip, setTip] = useState<Point | null>(null);
  const [track] = useState(() => makeTrack(side.result.contour!));
  const tipPoint = side.result.adjustable_points.find((p) => p.id === "pronasale")!;
  const tipAuto = side.result.landmarks.pronasale!;
  const [view, setView] = useState<"overlay" | "original">("overlay");
  const [hairline, setHairline] = useState<Point | null>(null);
  const [dialog, setDialog] = useState(false);
  const [speak, setSpeak] = useState(true);
  const trichion = result.landmarks.trichion!;
  const point = result.adjustable_points[0]!;
  const band = { min: 0.317, max: 0.35 };
  const rateLimited = new ApiError({ code: "rate_limited", status: 429, requestId: "req_0192f3a4b5c6d7e8f9a0b1c2d3", retryAfterS: 540 });
  const warning = config.strings.warning.distance_unverified ?? "";

  return (
    <Screen title="Components" onBack={back} wide>
      <p lang="en" className="max-w-page text-ink-2">
        Design tokens, type and core components for review, with the core's text from the
        committed fixtures and a line drawing of the synthetic face as the "photo". Switch the language in the top bar
        to see both. The print view arrives with the report (milestone 4).
      </p>

      <Section title="Colour tokens">
        <ul className="grid gap-3 md:grid-cols-2 lg:grid-cols-3">
          {COLOR_TOKENS.map(([name, use]) => (
            <Swatch key={name} name={name} use={use} />
          ))}
        </ul>
      </Section>

      <Section title="Type">
        <div className="space-y-4">
          {TYPE_SCALE.map(([cls, label]) => (
            <div key={cls}>
              <Label>{label}</Label>
              <p className={cls}>{config.strings.capture.frontal.title}</p>
            </div>
          ))}
          <div>
            <Label>Longest status text, 16 px, line height 1.7</Label>
            <p>{config.strings.status.inconclusive}</p>
          </div>
          <div>
            <Label>Tabular figures</Label>
            <p className="tabular-nums">
              0.333 · 1.00 · 32.0 mm · 5.0° · 111.1
              <br />
              0.317 – 0.350 · 30.0 mm – 34.0 mm
            </p>
          </div>
          <div className="grid gap-2 md:grid-cols-3">
            <p className="font-normal">400 {config.strings.reference.canon}</p>
            <p className="font-medium">500 {config.strings.reference.canon}</p>
            <p className="font-semibold">600 {config.strings.reference.canon}</p>
          </div>
        </div>
      </Section>

      <Section title="Buttons">
        <div className="flex flex-wrap items-center gap-3">
          <Button variant="primary">{t("subject.continue")}</Button>
          <Button variant="secondary">{t("preview.retake")}</Button>
          <Button variant="tertiary">{t("preview.chooseAnother")}</Button>
          <Button variant="primary" disabled>
            {t("subject.continue")}
          </Button>
        </div>
      </Section>

      <Section title="Top bar and step indicator">
        <div className="max-w-page border border-line">
          <TopBar onBack={() => undefined} step={step(t, "frontal")} />
        </div>
      </Section>

      <Section title="Form controls">
        <div className="grid gap-8 md:grid-cols-2">
          <div className="space-y-6">
            <TextField label={t("subject.age.label")} help={t("subject.age.help")} defaultValue="21" inputMode="numeric" />
            <TextField
              label={t("subject.age.label")}
              help={t("subject.age.help")}
              defaultValue="130"
              error={t("subject.age.error")}
            />
          </div>
          <div className="space-y-6">
            <div>
              <Label>Single choice</Label>
              <RadioCards
                labelledBy="components-sex"
                value={sex}
                onChange={setSex}
                options={SEXES.map((value) => ({ value, label: t(`subject.sex.${value}`) }))}
              />
              <span id="components-sex" hidden>
                {t("subject.sex.title")}
              </span>
            </div>
            <div>
              <Label>Segmented control</Label>
              <SegmentedControl
                label={t("viewer.label")}
                value={view}
                onChange={setView}
                options={[
                  { value: "overlay", label: t("viewer.overlay") },
                  { value: "original", label: t("viewer.original") },
                ]}
              />
            </div>
            <div>
              <Label>Checkbox (on, and off with its reason)</Label>
              <Checkbox label={t("live.speak")} checked={speak} onChange={setSpeak} />
              <Checkbox
                label={t("live.speak")}
                checked={false}
                disabled
                onChange={() => undefined}
                description={t("live.noVoice", { language: t(`languages.${language}`) })}
              />
            </div>
          </div>
        </div>
      </Section>

      <Section title="Notices and errors">
        <div className="max-w-page space-y-4">
          <Notice>
            <p>{warning}</p>
          </Notice>
          <Notice icon={false}>
            <p>{result.side_note}</p>
          </Notice>
          <ErrorMessage error={rateLimited} />
          <Label>Scan errors carry the actions their code allows.</Label>
          <ScanErrorPanel error={rateLimited} at={Date.UTC(2026, 8, 28, 2, 30)} onRetry={() => undefined} />
          <ScanErrorPanel
            error={new ApiError({ code: "token_stale", status: 400, requestId: "req_0192f3a4b5c6d7e8f9a0b1c2d4", retryAfterS: null })}
            at={0}
            onReanalyze={() => undefined}
            onStartOver={() => undefined}
          />
          <Button variant="secondary" onClick={() => setDialog(true)}>
            {t("results.newScan")}
          </Button>
          <ConfirmDialog
            open={dialog}
            onOpenChange={setDialog}
            title={t("newScan.title")}
            body={<p>{t("newScan.body")}</p>}
            confirm={t("newScan.confirm")}
            cancel={t("newScan.cancel")}
            onConfirm={() => undefined}
          />
        </div>
      </Section>

      <Section title="Upload and analysis states">
        <div className="max-w-page space-y-6">
          <div className="max-w-[16rem]">
            <PhotoViewer photoUrl={photoUrl} overlayUrl={null} result={result} dimmed controls={false} />
          </div>
          <div>
            <ProgressLine value={0.45} />
            <p className="mt-2 tabular-nums">{t("progress.uploading", { percent: 45 })}</p>
          </div>
          <div>
            <ProgressLine value={null} />
            <p className="mt-2">
              {t("progress.analyzing")} <span className="tabular-nums text-ink-3">{t("progress.elapsed", { seconds: 3 })}</span>
            </p>
          </div>
        </div>
      </Section>

      <Section title="Photo viewer (the core's user overlay on the synthetic photo)">
        <div className="max-w-page">
          <PhotoViewer photoUrl={photoUrl} overlayUrl={language === "th" ? overlayTh : overlayEn} result={result} />
          <Label>Pinch or double-tap to zoom, or use the buttons; the switch shows the original photo.</Label>
        </div>
      </Section>

      <Section title="Point adjustment">
        <div className="max-w-page">
          <p className="mb-2 font-medium">{point.name}</p>
          <p className="mb-4">{point.instruction}</p>
          <AdjustView
            photoUrl={photoUrl}
            result={result}
            pointId={point.id}
            pointName={point.name}
            value={hairline ?? { x: trichion.x!, y: trichion.y! }}
            adjusted={hairline !== null}
            onChange={setHairline}
          />
          <Label>
            Drag the point (the loupe appears), tap the photo, or use the arrow buttons and keys. A filled dot is automatic;
            a hollow ring has been moved.
          </Label>
        </div>
      </Section>

      <Section title="Point adjustment along the outline (fixtures/profile_ok)">
        <div className="max-w-page">
          <p className="mb-2 font-medium">{tipPoint.name}</p>
          <p className="mb-4">{tipPoint.instruction}</p>
          <AdjustView
            photoUrl={profilePhotoUrl}
            result={side.result}
            pointId={tipPoint.id}
            pointName={tipPoint.name}
            value={tip ?? { x: tipAuto.x!, y: tipAuto.y! }}
            adjusted={tip !== null}
            onChange={setTip}
            track={track}
            others={side.result.adjustable_points
              .filter((p) => p.id !== tipPoint.id && side.result.landmarks[p.id]?.available)
              .map((p) => ({ id: p.id, point: { x: side.result.landmarks[p.id]!.x!, y: side.result.landmarks[p.id]!.y! }, adjusted: false }))}
          />
          <Label>
            A silhouette point slides along the stored contour (drawn): drag, tap near the outline, or move it toward the
            forehead or the chin. The view&apos;s other points are the smaller dots.
          </Label>
        </div>
      </Section>

      <Section title="Facing choice (side photo)">
        <FacingChoice value={facing} onChange={setFacing} />
      </Section>

      <Section title="Capture-guide drawings">
        <div className="grid max-w-wide grid-cols-2 gap-6 md:grid-cols-4">
          {[
            <HelperDistanceDrawing key="d" distance={config.frontal.gates.camera_distance_recommended_m} />,
            <ZoomDrawing key="z" />,
            <SelfieDrawing key="s" />,
            <BackgroundDrawing key="b" />,
            <HairlineDrawing key="h" />,
            <LevelDrawing key="l" />,
            <NeutralDrawing key="n" />,
          ].map((drawing, i) => (
            <div key={i} className="border border-line bg-surface p-2">
              {drawing}
            </div>
          ))}
        </div>
      </Section>

      <Section title="Side-photo drawings">
        <div className="grid max-w-wide grid-cols-2 gap-6 md:grid-cols-4">
          {[
            <ProfileTurnDrawing key="t" distance={config.frontal.gates.camera_distance_recommended_m} />,
            <ProfileBackgroundDrawing key="b" />,
            <ProfileHairDrawing key="h" />,
            <ProfileGazeDrawing key="g" />,
            <ProfileNeckDrawing key="n" />,
            <AlarCreaseDrawing key="a" />,
          ].map((drawing, i) => (
            <div key={i} className="border border-line bg-surface p-2">
              {drawing}
            </div>
          ))}
        </div>
      </Section>

      <Section title="Range bar">
        <ul className="max-w-page space-y-3">
          {RANGE_EXAMPLES.map((r) => (
            <li key={r.label}>
              <Label>
                {r.label}: value {r.value}, band {band.min} – {band.max}
              </Label>
              <RangeBar value={r.value} min={band.min} max={band.max} status={r.status} />
            </li>
          ))}
        </ul>
      </Section>

      <Section title="Metric rows (one per status and confidence in the fixture)">
        <ul className="max-w-page border border-line bg-surface px-4">
          {sampleMetrics(result.metrics).map((m) => (
            <MetricRow key={`${m.name}-${m.status}`} metric={m} />
          ))}
        </ul>
      </Section>

      <Section title="Measurement sheet (fixtures/frontal_ok)">
        <div className="max-w-page space-y-4">
          <Notice icon={false}>
            <p>{result.side_note}</p>
            <p className="mt-2">{result.reference_note}</p>
          </Notice>
          <MeasurementSheet metrics={result.metrics} />
          <p className="text-sm text-ink-2">{result.disclaimer}</p>
          <ScanMeta date={new Date("2026-09-28T09:30:00+07:00")} versions={response.versions} />
        </div>
      </Section>
    </Screen>
  );
}
